function worksheetCheckPanelHTML(list, checkRowHTML) {
  return list.length
    ? '<section class="card no-print"><div class="card-h"><h2>Inspection checks' +
        '</h2></div><div class="card-b">' +
        `${list.map((c, ix) => checkRowHTML(c, ix, true)).join("")}` +
        "</div></section>"
    : "";
}
